import sys

def count_reachable_squares(R, C, K):
    directions = [(dr, dc) for dr in range(-1, 2) for dc in range(-1, 2) if (dr != 0 or dc != 0)]
    reachable = set()
    queue = [(R, C, 0)]
    while queue:
        r, c, moves = queue.pop(0)
        if (r, c) not in reachable:
            reachable.add((r, c))
            if moves < K:
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 1 <= nr <= 8 and 1 <= nc <= 8:
                        queue.append((nr, nc, moves + 1))
    return len(reachable)

input = sys.stdin.read().strip().split()
T = int(input[0])
results = []
index = 1
for _ in range(T):
    R = int(input[index])
    C = int(input[index + 1])
    K = int(input[index + 2])
    results.append(count_reachable_squares(R, C, K))
    index += 3
print('\n'.join(map(str, results)))
